using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.Menus;using GraphApi.Services.SGR.Menus;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.Menus{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Menus: creación, actualización y eliminación.")]    public class MenusMutation    {        [Authorize]        [GraphQLName("createMenus")]        [GraphQLDescription("Crea un nuevo Menu usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadMenus> CreateMenusAsync(            [GraphQLDescription("Datos necesarios para crear el Menu.")]            clCreateMenus objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Menu.")]            IMenusService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateMenus(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateMenus")]        [GraphQLDescription("Actualiza los campos especificados de un Menu existente.")]        public async Task<clReadMenus?> UpdateMenusAsync(            [GraphQLDescription("Datos del Menu a actualizar.")]            clUpdateMenus objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Menu.")]            IMenusService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateMenus(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteMenus")]        [GraphQLDescription("Elimina un Menu por su ID.")]        public async Task<bool> delMenusAsync(            [GraphQLDescription("ID del Menu a eliminar.")]            int nMenusID,            [Service]            [GraphQLDescription("Servicio para operaciones de Menu.")]            IMenusService objService        )        {            return await objService.DeleteMenus(nMenusID);        }    }}